plain=[{'poem_id': 507, 'rationale': 'The questions of oblivion and departure remain unresolved; a text-led opening avoids declaring whether the mythic boat sets sail.', 'status': 'pending'}, {'poem_id': 508, 'rationale': 'Keep the spiritual yearning and difficult ambiguity in the speaker’s words; avoid a literal death, vanishing body or sentimental escape landscape.', 'status': 'pending'}, {'poem_id': 512, 'rationale': 'The argument about truth, history and poetry benefits from direct reading rather than a balance, mask or courtroom cliché.', 'status': 'pending'}]
for p in (S/'content/editions/issue-27').glob('poem-*.json'):(B/p.name).write_bytes(p.read_bytes())
